1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode} as {@code <CITY3>-<LAST3>-<NNNN>}: the
11	 * upper-cased first three letters of the city and last name, plus a per-city 4-digit
12	 * sequence equal to one more than the owners already in that city.
13	 */
14	public class AssignOwnerCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city3 = prefix(owner.getCity());
18	        String last3 = prefix(owner.getLastName());
19	        long inCity = ownerRepository.findAll().stream()
20	                .filter(existing -> owner.getCity().equals(existing.getCity())).count();
21	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, inCity + 1));
22	    }
23	
24	    private static String prefix(String value) {
25	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
26	    }
27	}
