1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Computes the Luhn check digit (0-9) over the digits contained in a customer code,
5	 * doubling from the rightmost digit. Returns {@code null} when the code is absent, so
6	 * owners without a customer code carry no check digit.
7	 */
8	public final class CheckDigit {
9	
10	    private CheckDigit() {
11	    }
12	
13	    public static Integer of(String customerCode) {
14	        if (customerCode == null) {
15	            return null;
16	        }
17	        int sum = 0;
18	        boolean dbl = true;
19	        for (int i = customerCode.length() - 1; i >= 0; i--) {
20	            char c = customerCode.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (dbl) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            dbl = !dbl;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
