3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's locality (region). The postcode range is preferred (NSW 2000-2099,
9	 * VIC 3000-3099, QLD 4000-4099); when the postcode is absent or in no known range, the
10	 * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) is used instead. Any
11	 * city not listed yields "UNKNOWN".
12	 */
13	public final class Locality {
14	
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    private Locality() {
19	    }
20	
21	    public static String of(Owner owner) {
22	        String byPostcode = fromPostcode(owner.getPostcode());
23	        return byPostcode != null ? byPostcode : CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
24	    }
25	
26	    private static String fromPostcode(String postcode) {
27	        if (postcode == null || !postcode.matches("\\d{4}")) {
28	            return null;
29	        }
30	        int value = Integer.parseInt(postcode);
31	        if (value >= 2000 && value <= 2099) {
32	            return "NSW";
33	        }
34	        if (value >= 3000 && value <= 3099) {
35	            return "VIC";
36	        }
37	        if (value >= 4000 && value <= 4099) {
38	            return "QLD";
39	        }
40	        return null;
41	    }
42	}
