3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * Rejects a create when the owner supplies a postcode that is out of range for the
11	 * region derived from its city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city
12	 * with no known region, or an owner with no postcode, is accepted unchanged.
13	 */
14	public class EnsureOwnerPostcodeWithinRegion {
15	
16	    private static final Map<String, int[]> REGION_RANGE = Map.of(
17	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
18	
19	    public void service(@Val Owner owner) throws InvalidPostcodeException {
20	        String postcode = owner.getPostcode();
21	        int[] range = REGION_RANGE.get(Locality.of(owner));
22	        if (postcode == null || range == null) {
23	            return;
24	        }
25	        int value = Integer.parseInt(postcode);
26	        if (value < range[0] || value > range[1]) {
27	            throw new InvalidPostcodeException("Postcode " + postcode + " is not valid for this city");
28	        }
29	    }
30	}
