9	import org.springframework.http.ResponseEntity;
10	import org.springframework.samples.petclinic.mapper.OwnerMapper;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	
15	public class RespondWithOwnerCreated {
16	
17	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
18	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
19	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
20	        int namesakeCount = Namesakes.countBefore(owner, ownerRepository);
21	        int membershipLevel = MembershipLevel.of(owner, namesakeCount);
22	        dto.setNamesakeCount(namesakeCount);
23	        dto.setMembershipLevel(membershipLevel);
24	        dto.setBulkSignupWarning(BulkSignup.isWarned(owner, ownerRepository));
25	        LoggerFactory.getLogger("AUDIT").info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
26	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), membershipLevel);
27	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
28	    }
29	}
