11	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
12	import org.springframework.validation.annotation.Validated;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	@Validated
16	public class BuildOwner {
17	
18	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
19	            Out<Boolean> sharesHousehold) throws InvalidTelephoneException, AddressRequiredException {
20	        request.setTelephone(E164.normalize(request.getTelephone()));
21	        request.setAddress(Address.normalize(request.getAddress()));
22	        Owner owner = ownerMapper.toOwner(request);
23	        LocalDate registrationDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
24	        owner.setRegistrationDate(BusinessDay.rollForward(registrationDate));
25	        built.set(owner);
26	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
27	    }
28	}
