2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Counts the owners that already existed before {@code owner} (created earlier, hence a
8	 * lower id) sharing its first and last name, compared case-insensitively. This is the
9	 * owner's namesake count at the moment it was created.
10	 */
11	public final class Namesakes {
12	
13	    private Namesakes() {
14	    }
15	
16	    public static int countBefore(Owner owner, OwnerRepository ownerRepository) {
17	        Integer id = owner.getId();
18	        if (id == null) {
19	            return 0;
20	        }
21	        return (int) ownerRepository.findAll().stream()
22	                .filter(other -> other.getId() != null && other.getId() < id)
23	                .filter(other -> other.getLastName().equalsIgnoreCase(owner.getLastName()))
24	                .filter(other -> other.getFirstName().equalsIgnoreCase(owner.getFirstName()))
25	                .count();
26	    }
27	}
